package cn.guihualab.liveai;
import android.app.Application;import android.media.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadow.api.Shadow;import org.robolectric.util.ReflectionHelpers;import java.util.function.BooleanSupplier;import java.util.*;import java.io.ByteArrayOutputStream;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,shadows={NativePlaybackControlTest.TrackShadow.class})
public class NativePlaybackControlTest {
 @Implements(AudioTrack.class) public static class TrackShadow{
  volatile float rate=1,gain=1;volatile boolean deny;volatile int written,maxWrite,flushes;volatile String caller="";volatile boolean consume;volatile int parameterCalls;final ByteArrayOutputStream captured=new ByteArrayOutputStream();
  @Implementation public PlaybackParams getPlaybackParams(){parameterCalls++;if(deny)throw new IllegalArgumentException("No hardware speed API");return new PlaybackParams().allowDefaults().setSpeed(rate).setPitch(1);}
  @Implementation public void setPlaybackParams(PlaybackParams p){parameterCalls++;caller=Thread.currentThread().getName();if(deny)throw new IllegalArgumentException("unsupported synthetic speed");rate=p.getSpeed();}
  @Implementation public int setVolume(float value){gain=value;return 0;}@Implementation public int getPlaybackHeadPosition(){return consume?written/2:0;}
  @Implementation public int write(byte[] b,int offset,int size,int mode){maxWrite=Math.max(maxWrite,size);captured.write(b,offset,size);written+=size;return size;}
  @Implementation public void play(){}@Implementation public void pause(){}@Implementation public void flush(){flushes++;written=0;captured.reset();}@Implementation public void release(){}
 }
 private NativeAudio audio;private TrackShadow track;private volatile String error="";private volatile long stoppedMs=-1;private final List<PlaybackLedger.Ack> acknowledgements=Collections.synchronizedList(new ArrayList<>());
 @Before public void setup(){audio=new NativeAudio(RuntimeEnvironment.getApplication(),new NativeAudio.Listener(){public void microphone(byte[] b){}public void acknowledge(PlaybackLedger.Ack a){acknowledgements.add(a);}public void stopped(String r,String t,long ms){stoppedMs=ms;}public void routing(String i,String o,int t){}public void error(String e){error=e;}});AudioTrack output=Shadow.newInstanceOf(AudioTrack.class);track=Shadow.extract(output);ReflectionHelpers.setField(audio,"track",output);ReflectionHelpers.setField(audio,"running",true);ReflectionHelpers.callInstanceMethod(audio,"startPlaybackControls");}
 @After public void cleanup(){audio.close();}
 private void waitFor(BooleanSupplier condition)throws Exception{long until=System.currentTimeMillis()+2500;while(!condition.getAsBoolean()&&System.currentTimeMillis()<until)Thread.sleep(5);assertTrue(condition.getAsBoolean());}
 @Test public void softwareSpeedAppliesWithoutMainLooperOrAnyHardwareSpeedApi()throws Exception{
  track.deny=true;audio.settings(1.7f,.3f);waitFor(()->{try{return audio.playbackState().getString("status").equals("applied")&&Math.abs(audio.playbackState().getDouble("rate")-1.7)<.001;}catch(Exception e){return false;}});assertEquals(.3,track.gain,.001);assertEquals(0,track.parameterCalls);assertEquals(1,track.rate,0);assertEquals("software",audio.playbackState().getString("engine"));
 }

 @Test public void fullHardwareQueueDoesNotBlockSpeedChangesOrAcknowledgeUnplayedAudio()throws Exception{
  audio.play(new byte[96000],new JSONObject().put("chunk_id","c").put("run_id","r").put("turn_id","t"));Thread writer=new Thread(()->ReflectionHelpers.callInstanceMethod(audio,"playbackLoop"));ReflectionHelpers.setField(audio,"playback",writer);writer.start();waitFor(()->track.written>=9600);audio.settings(.75f,.4f);waitFor(()->{try{return Math.abs(audio.playbackState().getDouble("rate")-.75)<.001;}catch(Exception e){return false;}});assertTrue(track.maxWrite<=960);assertEquals(9600,track.written);assertEquals(0,track.flushes);assertEquals("",error);assertTrue(acknowledgements.isEmpty());audio.close();writer.join(1500);assertFalse(writer.isAlive());
 }
 @Test public void actualNativePlaybackWritesHalfDurationPcmEvenWhenHardwareRejectsSpeed()throws Exception{
  track.consume=true;track.deny=true;audio.settings(2,1);waitFor(()->{try{return audio.playbackState().getDouble("rate")==2;}catch(Exception e){return false;}});byte[] input=PcmTempoTest.tone(48000);JSONObject c=new JSONObject().put("chunk_id","short").put("run_id","r").put("turn_id","t");audio.play(input,c);audio.done(c);Thread writer=new Thread(()->ReflectionHelpers.callInstanceMethod(audio,"playbackLoop")),monitor=new Thread(()->ReflectionHelpers.callInstanceMethod(audio,"monitorLoop"));ReflectionHelpers.setField(audio,"playback",writer);ReflectionHelpers.setField(audio,"monitor",monitor);writer.start();monitor.start();waitFor(()->acknowledgements.size()==2);assertEquals(.5,(double)track.written/input.length,.04);assertEquals(220,PcmTempoTest.pitch(track.captured.toByteArray()),8);assertEquals(0,track.parameterCalls);assertEquals("playback.chunk.completed",acknowledgements.get(0).action);assertEquals("playback.completed",acknowledgements.get(1).action);assertEquals("",error);audio.close();writer.join(1500);monitor.join(1500);
 }
 @Test public void interruptDiscardsUnplayedSoftwareTailAndNextTurnStillCompletes()throws Exception{
  track.deny=true;audio.settings(2,1);waitFor(()->{try{return audio.playbackState().getDouble("rate")==2;}catch(Exception e){return false;}});JSONObject old=new JSONObject().put("chunk_id","old").put("run_id","r").put("turn_id","1"),next=new JSONObject().put("chunk_id","new").put("run_id","r").put("turn_id","2");audio.play(PcmTempoTest.tone(96000),old);audio.done(old);Thread writer=new Thread(()->ReflectionHelpers.callInstanceMethod(audio,"playbackLoop")),monitor=new Thread(()->ReflectionHelpers.callInstanceMethod(audio,"monitorLoop"));ReflectionHelpers.setField(audio,"playback",writer);ReflectionHelpers.setField(audio,"monitor",monitor);writer.start();monitor.start();waitFor(()->track.written>=9600);assertTrue(acknowledgements.isEmpty());audio.interrupt(old);assertEquals(0,stoppedMs);track.consume=true;audio.play(PcmTempoTest.tone(48000),next);audio.done(next);waitFor(()->acknowledgements.size()==2);assertEquals("new",acknowledgements.get(0).chunk);assertEquals("2",acknowledgements.get(1).turn);assertEquals(.5,track.written/96000d,.04);assertEquals(0,track.parameterCalls);audio.close();writer.join(1500);monitor.join(1500);
 }
}
